using System.Data;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using RevenuUsage.Domain.Entities;using RevenuUsage.Domain.Interfaces;namespace RevenuUsage.Infrastructure.Repositories;
public sealed class ReserveRepository:IReserveRepository{private readonly string _cs;public ReserveRepository(IConfiguration c)=>_cs=c.GetConnectionString("DB_Connection")!;public async Task<IEnumerable<ReserveSnapshot>>GetAsync(DateTime? from,DateTime? to,CancellationToken ct=default){await using var db=new SqlConnection(_cs);return await db.QueryAsync<ReserveSnapshot>(new CommandDefinition("dbo.uspGetReserveSnapshots",new{StartDate=from,EndDate=to},commandType:CommandType.StoredProcedure,cancellationToken:ct));}public async Task<Guid>CreateAsync(ReserveSnapshot x,string actor,CancellationToken ct=default){await using var db=new SqlConnection(_cs);return await db.QuerySingleAsync<Guid>(new CommandDefinition("dbo.uspCreateReserveSnapshot",new{x.ReserveDate,x.GoldValue,x.CashInHand,x.Deposits,x.Notes,CreatedBy=actor},commandType:CommandType.StoredProcedure,cancellationToken:ct));}public async Task DeleteAsync(Guid id,string actor,CancellationToken ct=default){await using var db=new SqlConnection(_cs);await db.ExecuteAsync(new CommandDefinition("dbo.uspDeleteReserveSnapshot",new{ReserveSnapshotId=id,DeletedBy=actor},commandType:CommandType.StoredProcedure,cancellationToken:ct));}}
